// Helper functions

func getEventRowClass(level string) string {
	switch level {
	case "ERROR":
		return "event-error"
	case "WARN":
		return "event-warning"
	case "BAN":
		return "event-ban"
	case "UNBAN":
		return "event-unban"
	default:
		return ""
	}
}

func getLevelBadgeClass(level string) string {
	switch level {
	case "ERROR":
		return "danger"
	case "WARN":
		return "warning"
	case "BAN":
		return "danger"
	case "UNBAN":
		return "success"
	case "INFO":
		return "info"
	default:
		return "secondary"
	}
}

func getActionBadgeClass(action string) string {
	switch action {
	case "ban":
		return "danger"
	case "unban":
		return "success"
	case "block":
		return "danger"
	case "detect":
		return "warning"
	case "warning":
		return "warning"
	case "error":
		return "danger"
	default:
		return "secondary"
	}
}

func truncateEvent(s string, max int) string {
	if len(s) <= max {
		return s
	}
	return s[:max-3] + "..."
}

func formatEventTime(ts string) string {
	// Return just the time portion if same day, otherwise full timestamp
	// For now just truncate to reasonable length
	if len(ts) > 19 {
		return ts[:19]
	}
	return ts
}

func showPageButton(i, current, total int) bool {
	// Always show first, last, and pages near current
	if i == 1 || i == total {
		return true
	}
	if i >= current-2 && i <= current+2 {
		return true
	}
	return false
}

